        /// whitespace (SP or HTAB) around it, and an empty one skipped, as a recipient must.
        fn elements(raw: &str) -> impl Iterator<Item = &str> {
            raw.split(',')
                .map(|element| element.trim_matches([' ', '\t']))
                .filter(|element| !element.is_empty())
        }
